// PxAFS field helpers: pin y's alternate-function-select field occupies
// bits [4y+2:4y] of PxAFS (nibble bit 3 is reserved). A pin drives AF<n>
// when its PxSEL bit is 1 and its PxAFS field is n; field 0 = AF0 (the
// legacy secondary function, the reset state).
#define PxAFS_SHIFT(pin)	((pin) * 4)
#define PxAFS_MASK(pin)		(0x7UL << PxAFS_SHIFT(pin))
#define PxAFS_VAL(pin, af)	(((uint32_t)(af) & 0x7UL) << PxAFS_SHIFT(pin))

/** GPIO0 Pins **/
// P0.0 primary function (when P0SEL(0) = '0'): GPIO0
#define GPIO0_BIT			(BIT0)
#define GPIO0_PxIN			(P0IN)
#define GPIO0_PxOUT			(P0OUT)
#define GPIO0_PxDIR			(P0DIR)
#define GPIO0_PxIES			(P0IES)
#define GPIO0_PxIFG			(P0IFG)
